from .api.types import module_types, report_types
from .exceptions import ValidationError


def validate_module_filters(**filters):
    """
    Checks if module parameters have correct types and allowed values.
    """
    _validate(module_types, filters)


def validate_report_filters(**filters):
    """
    Checks if report parameters have correct types and allowed values.
    """
    _validate(report_types, filters)


def _validate(validators, filters):
    for param, value in filters.items():
        try:
            validator = validators[param]
        except KeyError:
            raise ValidationError(f'Incorrect filter parameter {param!r}')
        if isinstance(validator, set):
            _validate_by_allowed_values(param, value, validator)
        else:
            _validate_by_type(param, value, validator)


def _validate_by_type(param, value, expected_type):
    if not isinstance(value, expected_type):
        raise ValidationError(f'Incorrect value {value!r} for parameter {param!r}. '
                              f'Type should be {expected_type!r}')


def _validate_by_allowed_values(param, value, allowed_values):
    if value not in allowed_values:
        raise ValidationError(f'Incorrect value {value!r} for parameter {param!r}. '
                              f'Allowed values: {list(allowed_values)}')
